from decimal import Decimal
from typing import Any


_ZERO = Decimal("0")


def _decimal(value: Any) -> Decimal:
    """Convert supported numeric values using decimal arithmetic."""
    if value is None:
        return _ZERO
    if isinstance(value, str):
        value = value.strip()
        if not value:
            return _ZERO
    return Decimal(str(value))


def sweep(
    accounts: list[dict], orders: list[dict]
) -> tuple[list[dict], list]:
    """Apply the nightly credit-hold sweep without mutating inputs."""
    new_accounts = [dict(account) for account in accounts]
    audits: list[tuple[str, Any]] = []

    orders_by_account: dict[Any, list[dict]] = {}
    for order in orders:
        if order.get("DEL_FLG") != "Y":
            orders_by_account.setdefault(order.get("ACCT_ID"), []).append(order)

    eligible_indices = [
        index
        for index, account in enumerate(new_accounts)
        if account.get("DEL_FLG") != "Y" and account.get("ACCT_TYP") == "C"
    ]
    eligible_indices.sort(key=lambda index: new_accounts[index].get("ACCT_ID"))

    for index in eligible_indices:
        account = new_accounts[index]
        account_id = account.get("ACCT_ID")

        exposure = _ZERO
        for order in orders_by_account.get(account_id, ()):
            if order.get("STAT_CD") == "I":
                exposure += _decimal(order.get("TOT_AMT"))

        credit_limit = _decimal(account.get("CRED_LIMIT"))
        held = account.get("CRED_HOLD") == "Y"

        if exposure > credit_limit and not held:
            account["CRED_HOLD"] = "Y"
            audits.append(("CRED_HOLD_ON", account_id))

        if exposure <= credit_limit * Decimal("8") / Decimal("10"):
            if account.get("CRED_HOLD") == "Y":
                account["CRED_HOLD"] = "N"
                audits.append(("CRED_HOLD_OFF", account_id))

    return new_accounts, audits
